  ('ex_step_down', '{"name":"پایین آمدن از پله (استپ داون)","purpose":"ایجاد کنترل اکسنتریک چهارسر و لگن برای پله.","howTo":["روی یک پله کوتاه بایستید.","پاشنه پای مقابل را آهسته به سمت زمین پایین ببرید.","زانو در راستای انگشتان میانی پا حرکت کند.","با فشار از پای ایستاده برگردید."],"commonMistakes":["جمع شدن زانو به داخل","پایین آمدن خیلی سریع","خم شدن بیش از حد تنه"],"whenToStop":"با درد تیز زانو یا از دست رفتن کنترل توقف شود."}'::jsonb),
  ('ex_dnf', '{"name":"تمرین فلکسورهای عمقی گردن","purpose":"بازآموزی فلکسورهای عمقی گردن برای حمایت از ستون گردنی.","howTo":["به پشت دراز بکشید و سر را روی زمین بگذارید.","به آرامی مثل «بله» گفتن سر را تکان دهید (چانه به داخل) بدون بلند کردن سر.","این انقباض ملایم را نگه دارید.","شل کنید و تکرار کنید."],"commonMistakes":["استفاده از عضلات سطحی گردن","بلند کردن سر","فشار زیاد در جمع کردن چانه"],"whenToStop":"با سرگیجه یا افزایش علائم دست توقف شود."}'::jsonb),
  ('ex_scap_control', '{"name":"کنترل کتف (سُر دادن روی دیوار)","purpose":"بهبود حرکت کتف و ریتم شانه.","howTo":["رو به دیوار بایستید و ساعدها را روی دیوار بگذارید.","دست‌ها را با حفظ تماس به بالا سُر دهید.","کتف‌ها را به آرامی به هم نزدیک و به بالا ببرید.","با کنترل پایین بیاورید."],"commonMistakes":["بالا انداختن بیش از حد شانه","قوس دادن کمر","از دست دادن تماس با دیوار"],"whenToStop":"با درد تیز شانه توقف شود."}'::jsonb),
  ('ex_ext_rotation', '{"name":"چرخش خارجی ایزومتریک","purpose":"بارگذاری روتیتور کاف با تحریک کم.","howTo":["بایستید و آرنج را ۹۰ درجه کنار بدن خم کنید.","پشت دست را به دیوار فشار دهید (چرخش به بیرون).","با شدتی راحت نگه دارید.","شل کنید و تکرار کنید."],"commonMistakes":["بالا انداختن شانه","فاصله گرفتن آرنج از بدن","نیروی زیاد در ابتدا"],"whenToStop":"با درد تیز یا رو به افزایش توقف شود."}'::jsonb),
  ('ex_ankle_balance', '{"name":"تعادل تک‌پا","purpose":"بازگرداندن حس عمقی مچ پا و کاهش خطر آسیب مجدد.","howTo":["نزدیک یک تکیه‌گاه روی یک پا بایستید.","زانو را کمی خم و وضعیت بدن را ثابت نگه دارید.","تا زمانی که کنترل دارید نگه دارید.","پا را عوض کنید."],"commonMistakes":["قفل کردن زانو","گرفتن تکیه‌گاه بدون نیاز","نگاه مداوم به پایین"],"whenToStop":"با درد تیز مچ پا یا خالی کردن پا توقف شود."}'::jsonb),
  ('ex_calf_raise', '{"name":"بالا رفتن روی پنجه (کاف ریز)","purpose":"تقویت مجموعه ساق و آشیل.","howTo":["صاف بایستید، پاها به عرض لگن.","روی سینه پا بالا بروید.","در بالا مکث کنید.","آهسته پایین بیایید."],"commonMistakes":["چرخیدن روی لبه خارجی پا","حرکت جهشی","دامنه ناقص"],"whenToStop":"با درد تیز آشیل یا پاشنه توقف شود."}'::jsonb),
  ('ex_hip_mobility', '{"name":"تحرک فلکسور لگن (نیم‌زانو)","purpose":"بهبود تحرک باز شدن لگن.","howTo":["روی یک زانو در حالت نیم‌زانو قرار بگیرید.","لگن را به آرامی به داخل جمع کنید و وزن را به جلو ببرید.","کشش را جلوی لگن حس کنید.","نگه دارید و برگردید."],"commonMistakes":["قوس دادن کمر","کشش بیش از حد","چرخاندن لگن"],"whenToStop":"با درد گیرکننده کشاله ران یا درد کمر توقف شود."}'::jsonb),
  ('ex_slr', '{"name":"بالا آوردن پای صاف","purpose":"تقویت عضله جلوی ران و خم‌کننده‌های لگن با زانوی کاملاً صاف.","howTo":["به پشت دراز بکشید؛ زانوی پای دیگر خم و کف آن روی زمین باشد.","عضله جلوی ران پای صاف را سفت کنید تا زانو کاملاً صاف شود.","پا را تا ارتفاع زانوی دیگر بالا بیاورید.","نگه دارید و با زانوی صاف آرام پایین بیاورید."],"commonMistakes":["خم شدن زانو هنگام بالا بردن","قوس دادن کمر","رها کردن سریع پا"],"whenToStop":"با درد تیز زانو یا کشاله ران، یا اگر زانو صاف نمی‌ماند، توقف کنید."}'::jsonb),
