  ('ex_split_squat', '{"name":"اسکوات با پای جلو و عقب (اسپلیت اسکوات)","purpose":"بارگذاری جداگانه هر پا برای قدرت و کنترل.","howTo":["با یک گام بلند بایستید؛ پاشنه پای عقب بالا باشد.","مستقیم پایین بروید تا ران جلو تقریباً افقی شود.","زانوی جلو در راستای انگشتان میانی و تنه صاف بماند.","با فشار پای جلو برگردید."],"commonMistakes":["جمع شدن زانوی جلو به داخل","خم شدن زیاد به جلو","گام کوتاه که فشار زانو را زیاد می‌کند"],"whenToStop":"با درد تیز زانو یا خالی کردن پا توقف کنید."}'::jsonb),
  ('ex_single_leg_squat', '{"name":"اسکوات تک‌پا تا روی جعبه","purpose":"قدرت و کنترل زانو روی یک پا، پیش از بازگشت به ورزش.","howTo":["روی یک پا جلوی یک جعبه یا صندلی بایستید.","باسن را به عقب و پایین ببرید تا آرام جعبه را لمس کنید.","زانو در راستای انگشتان میانی و لگن صاف بماند.","بدون کمک پای دیگر برخیزید."],"commonMistakes":["جمع شدن زانو به داخل","افتادن لگن در طرف مقابل","نشستن کامل روی جعبه"],"whenToStop":"با درد تیز، خالی کردن پا یا به هم خوردن راستا توقف کنید."}'::jsonb),
