  ('ex_hip_hinge', '{"name":"خم شدن از لگن با چوب","purpose":"یادگیری خم شدن به جلو از مفصل لگن با حفظ حالت طبیعی ستون فقرات.","howTo":["یک چوب را پشت بدن نگه دارید طوری که سر، بالای پشت و دنبالچه آن را لمس کنند.","زانوها را کمی شل کنید و لگن را به عقب ببرید.","هنگام خم شدن، هر سه نقطه تماس با چوب حفظ شود.","با جلو آوردن لگن برگردید."],"commonMistakes":["گرد شدن کمر","خم کردن زانو و تبدیل به اسکوات","جدا شدن سر یا دنبالچه از چوب"],"whenToStop":"با درد تیز کمر یا علائم پا توقف کنید."}'::jsonb),
  ('ex_copenhagen_short', '{"name":"کپنهاگ (اهرم کوتاه)","purpose":"تقویت عضلات کشاله ران؛ برای کاهش آسیب کشاله در ورزش‌های میدانی.","howTo":["به پهلو دراز بکشید؛ زانوی پای رویی روی نیمکت و آرنج زیر شانه.","با فشار زانوی رویی به نیمکت، لگن را بالا بیاورید.","اگر می‌توانید پای زیری را هم بالا بیاورید.","آرام پایین بیایید."],"commonMistakes":["افتادن لگن","چرخیدن به عقب","حرکت سریع"],"whenToStop":"با درد تیز کشاله توقف کنید."}'::jsonb),
  ('ex_hip_90_90', '{"name":"چرخش لگن ۹۰/۹۰","purpose":"بهبود چرخش داخلی و خارجی لگن.","howTo":["بنشینید؛ هر دو زانو ۹۰ درجه خم، یک پا جلو و یکی به پهلو.","تنه صاف بماند؛ در صورت نیاز دست‌ها پشت بدن.","هر دو زانو را به طرف دیگر بچرخانید.","آرام و در محدوده راحت حرکت کنید."],"commonMistakes":["خم شدن تنه","فشار به انتهای دامنه","بلند شدن پاها از زمین"],"whenToStop":"با درد گیرکننده کشاله توقف کنید."}'::jsonb),
  ('ex_cat_camel', '{"name":"گربه و شتر","purpose":"حرکت ملایم ستون فقرات برای کاهش خشکی بدون بار.","howTo":["روی چهار دست و پا قرار بگیرید.","آرام پشت را به سمت سقف گرد کنید.","سپس بگذارید کمر کمی پایین برود و سینه بالا بیاید.","نرم و در محدوده راحت حرکت کنید."],"commonMistakes":["فشار به انتهای دامنه","حرکت سریع","حبس نفس"],"whenToStop":"با درد تیز یا افزایش علائم پا توقف کنید."}'::jsonb),
  ('ex_prone_press_up', '{"name":"باز کردن کمر به حالت دمر (پرس‌آپ)","purpose":"باز کردن مکرر کمر برای بیمارانی که علائمشان با این حرکت بهتر می‌شود.","howTo":["دمر دراز بکشید؛ دست‌ها زیر شانه‌ها.","بالاتنه را با دست‌ها بالا ببرید و لگن روی زمین بماند.","بگذارید کمر شل شود و پایین بیفتد.","آرام پایین بیایید."],"commonMistakes":["بلند شدن لگن","سفت کردن باسن","ادامه با وجود درد"],"whenToStop":"اگر درد به سمت پایین پا پخش شد توقف کنید."}'::jsonb),
  ('ex_knee_to_chest', '{"name":"آوردن یک زانو به سینه","purpose":"کشش ملایم خم شدن کمر برای خشکی یا دردی که با خم شدن بهتر می‌شود.","howTo":["به پشت دراز بکشید؛ هر دو زانو خم.","با دو دست یک زانو را به سمت سینه بیاورید.","کشش راحت را نگه دارید.","پایین بیاورید و طرف دیگر را انجام دهید."],"commonMistakes":["بلند کردن سر","کشیدن شدید تا حد درد","حبس نفس"],"whenToStop":"اگر علائم پا بیشتر شد توقف کنید."}'::jsonb),
  ('ex_pelvic_tilt', '{"name":"تیلت لگن","purpose":"یادگیری حرکت کوچک و کنترل‌شده کمر و لگن در درد زیاد.","howTo":["به پشت دراز بکشید؛ زانوها خم و کف پاها روی زمین.","با چرخاندن لگن، کمر را آرام به زمین بچسبانید.","سپس کمی قوس دهید.","آرام بین این دو حالت حرکت کنید."],"commonMistakes":["بلند کردن باسن","هل دادن با پاها","حرکت با دامنه زیاد"],"whenToStop":"با درد تیز توقف کنید."}'::jsonb),
  ('ex_dead_bug', '{"name":"دد باگ","purpose":"تمرین کنترل تنه هنگام حرکت دست‌ها و پاها.","howTo":["به پشت دراز بکشید؛ لگن و زانو ۹۰ درجه، دست‌ها رو به سقف.","کمر آرام روی زمین بماند.","دست و پای مخالف را آهسته به سمت زمین پایین ببرید.","برگردید و طرف دیگر را انجام دهید."],"commonMistakes":["جدا شدن کمر از زمین","حرکت سریع","حبس نفس"],"whenToStop":"با درد تیز کمر توقف کنید."}'::jsonb),
  ('ex_sciatic_slider', '{"name":"لغزاندن عصب سیاتیک (نشسته)","purpose":"لغزاندن ملایم عصب سیاتیک بدون کشیدن آن.","howTo":["صاف روی صندلی بنشینید.","زانو را صاف کنید و هم‌زمان به بالا نگاه کنید.","زانو را خم کنید و هم‌زمان به پایین نگاه کنید.","نرم حرکت کنید؛ دو انتها در جهت مخالف حرکت می‌کنند."],"commonMistakes":["نگه داشتن حالت کشیده","حرکت تا حد گزگز شدید","قوز شدید کمر"],"whenToStop":"با گزگز، بی‌حسی یا دردی که می‌ماند و بیشتر می‌شود توقف کنید."}'::jsonb),
  ('ex_walking_program', '{"name":"پیاده‌روی تدریجی","purpose":"افزایش تحمل فعالیت عمومی در درد مزمن.","howTo":["با سرعت راحت و یکنواخت راه بروید.","حتی اگر احساس می‌کنید می‌توانید بیشتر بروید، به زمان تعیین‌شده پایبند باشید.","طبق توافق، زمان را تدریجی افزایش دهید.","حال روز بعد خود را یادداشت کنید."],"commonMistakes":["زیاده‌روی در روزهای خوب","کنار گذاشتن کامل در روزهای بد","راه رفتن خیلی سریع"],"whenToStop":"با درد قفسه سینه، تنگی نفس نامتناسب یا علائم جدید پا توقف کنید."}'::jsonb),
  ('ex_dnf_head_lift', '{"name":"چانه به داخل با بلند کردن سر","purpose":"پیشرفت تمرین عضلات عمقی جلوی گردن در برابر جاذبه.","howTo":["بدون بالش به پشت دراز بکشید؛ زانوها خم.","مثل چانه به داخل، چانه را آرام پایین بیاورید.","با حفظ این حالت، سر را حدود ۲ سانتی‌متر از زمین بلند کنید.","نگه دارید؛ ابتدا سر را پایین بگذارید و بعد چانه را رها کنید."],"commonMistakes":["جلو رفتن چانه هنگام بلند کردن","بالا بردن زیاد سر","حبس نفس"],"whenToStop":"با سردرد، سرگیجه یا علائم در دست توقف کنید."}'::jsonb),
  ('ex_cervical_rotation', '{"name":"چرخش گردن","purpose":"حفظ چرخش راحت گردن.","howTo":["صاف بنشینید و شانه‌ها شل باشند.","سر را آرام تا جایی که راحت است به یک طرف بچرخانید.","به وسط برگردید.","به طرف دیگر تکرار کنید."],"commonMistakes":["حرکت سریع","کج شدن سر هنگام چرخش","بالا آمدن شانه‌ها"],"whenToStop":"با سرگیجه، تغییر دید یا علائم در دست توقف کنید."}'::jsonb),
  ('ex_scap_retraction', '{"name":"جمع کردن کتف‌ها","purpose":"فعال کردن عضلات میانه پشت که از گردن و شانه حمایت می‌کنند.","howTo":["صاف بنشینید یا بایستید؛ دست‌ها شل.","کتف‌ها را آرام به عقب و کمی پایین بکشید.","بدون بالا انداختن شانه نگه دارید.","آرام رها کنید."],"commonMistakes":["بالا انداختن شانه‌ها","قوس دادن کمر","فشار بیش از حد"],"whenToStop":"با درد تیز یا علائم در دست توقف کنید."}'::jsonb),
  ('ex_upper_trap_stretch', '{"name":"کشش ذوزنقه فوقانی","purpose":"کاهش سفتی کنار گردن.","howTo":["صاف بنشینید و با یک دست لبه صندلی را بگیرید.","سر را به طرف مخالف خم کنید؛ گوش به سمت شانه.","کشش ملایم را کنار گردن حس کنید.","نگه دارید و آرام برگردید."],"commonMistakes":["کشیدن سر با زور","چرخاندن سر","بالا آمدن شانه طرف ثابت"],"whenToStop":"با گزگز در دست یا سرگیجه توقف کنید."}'::jsonb),
  ('ex_neck_isometrics', '{"name":"ایزومتریک گردن","purpose":"فعال کردن ملایم عضلات بدون حرکت گردن.","howTo":["صاف بنشینید و یک دست را روی پیشانی بگذارید.","سر را آرام به دست فشار دهید بدون اینکه حرکت کند.","نگه دارید و شل کنید.","به عقب و هر دو طرف تکرار کنید."],"commonMistakes":["فشار زیاد","حرکت کردن سر","حبس نفس"],"whenToStop":"با سردرد، سرگیجه یا علائم در دست توقف کنید."}'::jsonb),
  ('ex_median_nerve_slider', '{"name":"لغزاندن عصب مدین","purpose":"لغزاندن ملایم عصب مدین در علائم دست با منشأ گردنی.","howTo":["بایستید؛ دست به پهلو، آرنج خم و کف دست رو به بالا.","آرنج و مچ را صاف کنید و سر را به سمت همان دست خم کنید.","آرنج و مچ را خم کنید و سر را به طرف مخالف خم کنید.","نرم حرکت کنید؛ دو انتها در جهت مخالف حرکت می‌کنند."],"commonMistakes":["نگه داشتن حالت کشیده","حرکت تا حد گزگز شدید","بالا انداختن شانه"],"whenToStop":"با گزگز، بی‌حسی یا دردی که می‌ماند و بیشتر می‌شود توقف کنید."}'::jsonb),
  ('ex_pendulum', '{"name":"آونگی","purpose":"حرکت شل و با کمک جاذبه شانه در درد زیاد.","howTo":["به جلو خم شوید و دست سالم را روی میز بگذارید.","بگذارید دست دردناک شل آویزان شود.","بدن را آرام تکان دهید تا دست در دایره‌های کوچک بچرخد.","عضلات شانه شل بمانند."],"commonMistakes":["بالا بردن دست با عضلات شانه","دایره‌های بزرگ و سریع","ایستادن بیش از حد صاف"],"whenToStop":"با درد تیز یا گزگز دست توقف کنید."}'::jsonb),
  ('ex_shoulder_flexion_aaro', '{"name":"بالا بردن شانه با کمک چوب","purpose":"بازگرداندن دامنه بالای سر با کمک دست دیگر.","howTo":["به پشت دراز بکشید و چوب را با دو دست بگیرید.","با دست سالم هر دو دست را بالای سر ببرید.","تا جایی که راحت است بروید و نگه دارید.","آرام پایین بیاورید."],"commonMistakes":["قوس دادن کمر","بالا انداختن شانه","فشار تا حد درد تیز"],"whenToStop":"با درد تیز یا گیر کردن شانه توقف کنید."}'::jsonb),
  ('ex_er_band', '{"name":"چرخش خارجی با کش","purpose":"تقویت روتاتور کاف خلفی.","howTo":["پهلو به محل بستن کش بایستید؛ آرنج کنار بدن و ۹۰ درجه خم.","یک حوله کوچک بین آرنج و بدن کمک می‌کند.","ساعد را در برابر کش به بیرون بچرخانید.","آرام برگردید."],"commonMistakes":["دور شدن آرنج از بدن","چرخاندن تنه","بالا انداختن شانه"],"whenToStop":"با درد تیز شانه توقف کنید."}'::jsonb),
  ('ex_ir_band', '{"name":"چرخش داخلی با کش","purpose":"تقویت چرخاننده‌های داخلی شانه.","howTo":["پهلو به محل بستن کش بایستید؛ دست تمرینی نزدیک کش و آرنج ۹۰ درجه.","آرنج کنار بدن بماند.","ساعد را به داخل و جلوی بدن بچرخانید.","آرام برگردید."],"commonMistakes":["دور شدن آرنج از بدن","چرخاندن تنه","حرکت سریع"],"whenToStop":"با درد تیز شانه توقف کنید."}'::jsonb),
  ('ex_row_band', '{"name":"پارویی با کش","purpose":"تقویت عضلات میانه پشت و کتف.","howTo":["کش را هم‌سطح سینه ببندید و هر سر را با یک دست بگیرید.","صاف بایستید؛ دست‌ها جلو.","آرنج‌ها را به عقب بکشید و کتف‌ها را به هم نزدیک کنید.","آرام برگردید."],"commonMistakes":["بالا انداختن شانه","خم شدن به عقب","کشیدن با دست به جای آرنج"],"whenToStop":"با درد تیز شانه یا گردن توقف کنید."}'::jsonb),
  ('ex_prone_t', '{"name":"بالا بردن دست‌ها به شکل T (دمر)","purpose":"تقویت عضلات کنترل‌کننده کتف.","howTo":["دمر دراز بکشید؛ دست‌ها به پهلو و شست رو به بالا.","کتف‌ها را آرام به عقب بکشید.","دست‌ها را چند سانتی‌متر بالا ببرید.","نگه دارید و آرام پایین بیاورید."],"commonMistakes":["بالا انداختن شانه","بلند کردن سر یا سینه","تاب دادن دست‌ها"],"whenToStop":"با درد تیز شانه یا گردن توقف کنید."}'::jsonb),
  ('ex_cross_body_stretch', '{"name":"کشش ضربدری جلوی بدن","purpose":"کشش پشت شانه.","howTo":["یک دست را از جلوی سینه به طرف دیگر ببرید.","با دست دیگر از آرنج آرام آن را نزدیک‌تر کنید.","کتف پایین بماند.","نگه دارید و آرام رها کنید."],"commonMistakes":["بالا انداختن شانه","چرخاندن تنه","کشیدن تا حد درد"],"whenToStop":"با درد گیرکننده جلوی شانه توقف کنید."}'::jsonb),
  ('ex_wall_pushup_plus', '{"name":"شنای دیواری پلاس","purpose":"تقویت دندانه‌ای قدامی برای حمایت از حرکت کتف.","howTo":["رو به دیوار بایستید؛ دست‌ها هم‌سطح شانه.","یک شنای کوچک روی دیوار انجام دهید.","در انتها بیشتر فشار دهید تا کتف‌ها از هم باز شوند.","آرام برگردید."],"commonMistakes":["افتادن لگن","بالا انداختن شانه","انجام ندادن فشار انتهایی"],"whenToStop":"با درد تیز شانه توقف کنید."}'::jsonb),
  ('ex_sidelying_er', '{"name":"چرخش خارجی به پهلو","purpose":"بارگذاری روتاتور کاف خلفی با وزنه.","howTo":["روی طرف غیرتمرینی دراز بکشید؛ حوله زیر آرنج تمرینی.","آرنج کنار بدن و ۹۰ درجه خم بماند.","ساعد را به سمت سقف بچرخانید.","آرام پایین بیاورید."],"commonMistakes":["چرخیدن تنه به عقب","جدا شدن آرنج از حوله","وزنه سنگین با کنترل ضعیف"],"whenToStop":"با درد تیز شانه توقف کنید."}'::jsonb),
  ('ex_ankle_alphabet', '{"name":"نوشتن حروف با مچ پا","purpose":"حرکت مچ پا در همه جهت‌ها در مراحل اولیه پس از آسیب.","howTo":["بنشینید؛ ساق پا تکیه داشته و پا آزاد باشد.","با شست پا حروف الفبا را در هوا بنویسید.","حرکت از مچ باشد، نه از زانو.","در محدوده راحت حرکت کنید."],"commonMistakes":["حرکت دادن کل پا","فشار به جهت‌های دردناک","عجله"],"whenToStop":"با درد تیز یا افزایش ورم توقف کنید."}'::jsonb),
  ('ex_ankle_band_4way', '{"name":"مچ پا چهارجهته با کش","purpose":"تقویت مچ پا به بالا، پایین، داخل و خارج.","howTo":["بنشینید؛ پا صاف و کش دور پنجه.","پنجه را در برابر کش به پایین فشار دهید و آرام برگردید.","با بستن مناسب کش، بالا کشیدن، چرخش به داخل و به خارج را تکرار کنید.","فقط مچ پا حرکت کند."],"commonMistakes":["چرخاندن کل پا به جای مچ","برگشت سریع","کش خیلی سفت"],"whenToStop":"با درد تیز توقف کنید."}'::jsonb),
  ('ex_eccentric_heel_drop', '{"name":"پایین آوردن اکسنتریک پاشنه","purpose":"بارگذاری تدریجی در تاندینوپاتی آشیل.","howTo":["لبه پله بایستید؛ پاشنه‌ها بیرون از لبه.","روی هر دو پنجه بالا بروید.","وزن را روی یک پا ببرید و پاشنه را آرام پایین‌تر از پله بیاورید.","با هر دو پا بالا برگردید."],"commonMistakes":["پایین آمدن سریع","چرخیدن مچ به بیرون","تکان دادن در پایین"],"whenToStop":"با درد تیز یا اگر درد و خشکی صبح روز بعد بیشتر شد توقف کنید."}'::jsonb),
  ('ex_soleus_raise', '{"name":"بالا رفتن روی پنجه با زانوی خم","purpose":"هدف‌گیری عضله نعلی که برای استقامت راه رفتن و دویدن مهم است.","howTo":["نزدیک دیوار بایستید؛ زانوها کمی خم.","با حفظ خم بودن زانو روی پنجه بالا بروید.","در بالا مکث کنید.","آرام پایین بیایید."],"commonMistakes":["صاف کردن زانوها","افتادن وزن روی لبه بیرونی پا","عجله"],"whenToStop":"با درد تیز ساق یا آشیل توقف کنید."}'::jsonb),
  ('ex_plantar_fascia_stretch', '{"name":"کشش فاسیای کف پا","purpose":"کاهش درد پاشنه، به‌ویژه پیش از اولین قدم‌های صبح.","howTo":["بنشینید و پای درگیر را روی زانوی دیگر بگذارید.","انگشتان پا را به سمت ساق عقب بکشید.","کشش را در قوس کف پا حس کنید.","نگه دارید و رها کنید."],"commonMistakes":["کشیدن مچ به جای انگشتان","تکان دادن","کشش تا حد درد تیز"],"whenToStop":"با درد تیز یا سوزشی توقف کنید."}'::jsonb),
  ('ex_short_foot', '{"name":"کوتاه کردن پا (شورت فوت)","purpose":"تقویت عضلات کوچک نگه‌دارنده قوس پا.","howTo":["بنشینید؛ کف پا روی زمین.","با نزدیک کردن برجستگی جلوی پا به پاشنه، پا را کوتاه کنید.","انگشتان کشیده و شل بمانند.","نگه دارید و شل کنید."],"commonMistakes":["جمع کردن انگشتان","بلند کردن پاشنه","چرخیدن پا به بیرون"],"whenToStop":"با گرفتگی یا درد تیز توقف کنید."}'::jsonb),
  ('ex_balance_reach', '{"name":"دسترسی تک‌پا","purpose":"تمرین تعادل پویا در چند جهت (به سبک ستاره).","howTo":["روی یک پا با زانوی کمی خم بایستید.","پای دیگر را به جلو، کنار و عقب ببرید و آرام زمین را لمس کنید.","بین هر دسترسی به مرکز برگردید.","زانوی پای ایستاده بالای انگشتان بماند."],"commonMistakes":["گذاشتن وزن روی پای دسترسی","جمع شدن زانو به داخل","خم شدن زیاد تنه"],"whenToStop":"با درد تیز یا از دست دادن مکرر تعادل توقف کنید."}'::jsonb),
  ('ex_hop_progression', '{"name":"پیشرفت پرش","purpose":"افزایش کنترل فرود و قدرت واکنشی پیش از بازگشت به ورزش.","howTo":["با پرش‌های کوچک دوپا درجا شروع کنید.","نرم فرود بیایید؛ زانوها بالای انگشتان.","وقتی پرش دوپا آسان شد به پرش تک‌پا بروید.","پس از هر فرود لحظه‌ای ثابت بمانید."],"commonMistakes":["فرود خشک و پرصدا","جمع شدن زانو به داخل","پیشرفت سریع"],"whenToStop":"با درد تیز، خالی کردن پا یا ورم پس از تمرین توقف کنید."}'::jsonb);

insert into public.exercise_catalog_versions (
  exercise_id, version, patient_content, content_hash, active
)
select source.exercise_id, 1, source.patient_content,
       encode(extensions.digest(source.patient_content::text, 'sha256'), 'hex'),
       false
from pg_temp.exercise_library_031 source
on conflict (exercise_id, version) do nothing;

-- Fail closed if a database already holds different content under the same
-- id and version, rather than silently keeping it.
do $$
begin
  if exists (
    select 1
    from pg_temp.exercise_library_031 source
    join public.exercise_catalog_versions catalog
      on catalog.exercise_id = source.exercise_id and catalog.version = 1
    where catalog.patient_content is distinct from source.patient_content
  ) then
    raise exception using
      errcode = '23505',
      message = 'Exercise catalog version 1 already exists with different content';
  end if;
end $$;

commit;

update public.schema_migrations
set status = 'applied', applied_at = clock_timestamp()
where version = '031' and status = 'applying';

select '031_exercise_library_expansion.sql applied' as result;
